class Solution { struct Node{array<int,26> next;int id;Node():id(-1){next.fill(-1);}};vector<Node> trie;int getId(const string& word,unordered_map<string,int>& ids){auto found=ids.find(word);if(found!=ids.end())return found->second;int id=ids.size();ids[word]=id;int node=0;for(char letter:word){int index=letter-'a',next=trie[node].next[index];if(next==-1){next=trie.size();trie[node].next[index]=next;trie.emplace_back();}node=next;}trie[node].id=id;return id;}public:long long minimumCost(string source,string target,vector<string>& original,vector<string>& changed,vector<int>& cost){trie.clear();trie.emplace_back();unordered_map<string,int> ids;for(int i=0;i<(int)cost.size();++i){getId(original[i],ids);getId(changed[i],ids);}const long long INF=LLONG_MAX/4;vector<vector<long long>> distance(ids.size(),vector<long long>(ids.size(),INF));for(int node=0;node<(int)ids.size();++node)distance[node][node]=0;for(int i=0;i<(int)cost.size();++i){int from=ids[original[i]],to=ids[changed[i]];distance[from][to]=min(distance[from][to],1LL*cost[i]);}for(int middle=0;middle<(int)distance.size();++middle)for(int from=0;from<(int)distance.size();++from)if(distance[from][middle]<INF)for(int to=0;to<(int)distance.size();++to)if(distance[middle][to]<INF)distance[from][to]=min(distance[from][to],distance[from][middle]+distance[middle][to]);vector<long long> dp(source.size()+1,INF);dp[0]=0;for(int start=0;start<(int)source.size();++start){if(dp[start]==INF)continue;if(source[start]==target[start])dp[start+1]=min(dp[start+1],dp[start]);int fromNode=0,toNode=0;for(int end=start;end<(int)source.size();++end){fromNode=trie[fromNode].next[source[end]-'a'];toNode=trie[toNode].next[target[end]-'a'];if(fromNode==-1||toNode==-1)break;int fromId=trie[fromNode].id,toId=trie[toNode].id;if(fromId>=0&&toId>=0&&distance[fromId][toId]<INF)dp[end+1]=min(dp[end+1],dp[start]+distance[fromId][toId]);}}return dp[source.size()]==INF?-1:dp[source.size()];} };
